//! Runtime security gateway for AI coding agents building with native dependencies.
//!
//! `sandbox-ffi-layers` intercepts build commands executed by AI coding agents
//! (Claude Code, Codex, OpenCode) and verifies native dependency supply chain
//! before allowing `build.rs`, `proc-macro`, or CFFI execution.

mod cargo_lock;

use anyhow::Result;
use clap::Parser;
use serde::Serialize;
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Parser)]
#[command(name = "sandbox-ffi", version, about)]
struct Cli {
    /// Check Cargo.lock for supply-chain risks (one-shot mode)
    #[arg(short, long)]
    check: bool,

    /// Watch mode: intercept build commands via eBPF (requires root)
    #[arg(short, long)]
    watch: bool,

    /// Path to Cargo.lock (default: ./Cargo.lock)
    #[arg(short, long, default_value = "./Cargo.lock")]
    lockfile: String,

    /// Output format: text, json, sarif
    #[arg(short, long, default_value = "text")]
    format: String,

    /// Output JSON format (shortcut for --format json)
    #[arg(long)]
    json: bool,

    /// Exit with code 1 on critical findings
    #[arg(short, long)]
    fail_critical: bool,
}

#[derive(Serialize)]
struct JsonOutput {
    version: String,
    timestamp: String,
    summary: JsonSummary,
    results: Vec<JsonResult>,
}

#[derive(Serialize)]
struct JsonSummary {
    total: usize,
    errors: usize,
    warnings: usize,
    passed: usize,
}

#[derive(Serialize)]
struct JsonResult {
    id: String,
    severity: String,
    message: String,
    file: String,
    line: usize,
    suggestion: Option<String>,
}

fn current_timestamp() -> String {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    // Simple UTC epoch formatting without heavy external crates like chrono
    let secs_per_day = 86400;
    let days = now / secs_per_day;
    let remainder = now % secs_per_day;
    let hours = remainder / 3600;
    let minutes = (remainder % 3600) / 60;
    let seconds = remainder % 60;

    let (year, month, day) = epoch_days_to_date(days);
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z",
        year, month, day, hours, minutes, seconds
    )
}

fn epoch_days_to_date(mut days: u64) -> (u32, u32, u32) {
    // Gregorian calendar epoch algorithm from days since 1970-01-01
    days += 719468;
    let eras = days / 146097;
    let doe = days % 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = (yoe as u64) + eras * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5) + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    (y as u32, m as u32, d as u32)
}

fn main() -> Result<()> {
    let args = Cli::parse();
    let json_mode = args.json || args.format == "json";

    if !json_mode {
        tracing_subscriber::fmt()
            .with_env_filter("sandbox_ffi_layers=info")
            .init();
    }

    if args.check {
        let content = std::fs::read_to_string(&args.lockfile)?;
        let packages = cargo_lock::parse_cargo_lock(&content)?;
        let surfaces = cargo_lock::analyze_native_surface(&packages);

        if !json_mode {
            tracing::info!(
                "Analyzed {} packages, {} have native build surface",
                packages.len(),
                surfaces.len()
            );

            for surface in &surfaces {
                let risk = if surface.has_proc_macro {
                    "PROC-MACRO"
                } else {
                    "BUILD"
                };
                println!(
                    "  [{}] {}@{} — {}",
                    risk,
                    surface.package.name,
                    surface.package.version,
                    if surface.has_proc_macro {
                        "proc-macro crate"
                    } else {
                        "build script dep"
                    }
                );
            }
        }

        // Check for known-malicious patterns (proc-macro1 == typosquat)
        let malicious: Vec<_> = packages
            .iter()
            .filter(|p| p.name == "proc-macro1" || p.name == "proc-macro-en")
            .collect();

        if json_mode {
            let mut results = Vec::new();
            for surface in &surfaces {
                let (id, severity, msg) = if surface.has_proc_macro {
                    ("proc-macro-surface", "warning", format!("Proc-macro crate detected: {}@{}", surface.package.name, surface.package.version))
                } else {
                    ("native-build-surface", "warning", format!("Native build dependency detected: {}@{}", surface.package.name, surface.package.version))
                };
                results.push(JsonResult {
                    id: id.to_string(),
                    severity: severity.to_string(),
                    message: msg,
                    file: args.lockfile.clone(),
                    line: 0,
                    suggestion: Some("Review dependency graph for supply-chain risks".to_string()),
                });
            }

            for m in &malicious {
                results.push(JsonResult {
                    id: "known-malicious-package".to_string(),
                    severity: "error".to_string(),
                    message: format!("Known malicious package blocked: {}@{}", m.name, m.version),
                    file: args.lockfile.clone(),
                    line: 0,
                    suggestion: Some("Remove or replace compromised dependency immediately".to_string()),
                });
            }

            let errors = malicious.len();
            let warnings = surfaces.len();
            let total = packages.len();
            let passed = total.saturating_sub(errors + warnings);

            let output = JsonOutput {
                version: "1.0.0".to_string(),
                timestamp: current_timestamp(),
                summary: JsonSummary {
                    total,
                    errors,
                    warnings,
                    passed,
                },
                results,
            };

            println!("{}", serde_json::to_string_pretty(&output)?);

            if !malicious.is_empty() && args.fail_critical {
                std::process::exit(1);
            }
        } else {
            if !malicious.is_empty() {
                eprintln!("⚠️  KNOWN-MALICIOUS PACKAGES DETECTED:");
                for m in &malicious {
                    eprintln!("  BLOCKED: {}@{}", m.name, m.version);
                }
                if args.fail_critical {
                    std::process::exit(1);
                }
            }
        }
    } else if args.watch {
        if json_mode {
            let output = JsonOutput {
                version: "1.0.0".to_string(),
                timestamp: current_timestamp(),
                summary: JsonSummary { total: 0, errors: 1, warnings: 0, passed: 0 },
                results: vec![JsonResult {
                    id: "watch-mode-unsupported".to_string(),
                    severity: "error".to_string(),
                    message: "Watch mode requires eBPF support (coming in v0.2.0)".to_string(),
                    file: "".to_string(),
                    line: 0,
                    suggestion: Some("Use --check for one-shot analysis".to_string()),
                }],
            };
            println!("{}", serde_json::to_string_pretty(&output)?);
            std::process::exit(2);
        } else {
            eprintln!("Watch mode requires eBPF support (coming in v0.2.0)");
            eprintln!("Use --check for one-shot analysis");
            std::process::exit(2);
        }
    } else {
        if json_mode {
            let output = JsonOutput {
                version: "1.0.0".to_string(),
                timestamp: current_timestamp(),
                summary: JsonSummary { total: 0, errors: 0, warnings: 0, passed: 0 },
                results: vec![],
            };
            println!("{}", serde_json::to_string_pretty(&output)?);
        } else {
            println!("sandbox-ffi-layers v{}", env!("CARGO_PKG_VERSION"));
            println!("Use --check to analyze a Cargo.lock, or --watch for runtime monitoring");
        }
    }

    Ok(())
}

